INSERT INTO `ucp_news` (`id`, `title`, `created`, `content`, `image`, `meta`, `creator`) VALUES
(24, 'RaiseMTA', '2025-06-15 21:57:05', 'Sziasztok! Elérkeztünk a [[v4green]][[**]]RaiseMTA [[**]][[nocol]] [[v4blue]]nyitásához[[nocol]]! Rengeteg [[**]][[v4red]]hibajavítást[[nocol]] végeztünk[[**]]el az utóbbi időben, volt [[v4blue]]két BETA tesztünk[[nocol]] is, ami igencsak jól sikeredett. Úgy gondoljuk, hogy eleget [[v4red]]várattunk [[nocol]]titeket.\r\n\r\nA jövőben rengeteg [[v4blue]]új fejlesztés[[nocol]] várható, pár példa:\r\n\r\n[[v4green]][[**]]- Házrablás[[**]][[nocol]]\r\n[[**]][[v4blue]]- Olajvállalat[[nocol]][[**]]\r\n[[**]][[v4red]]- Ékszerbolt rablás.[[nocol]][[**]]\r\n', 'feed/ucp_v4/5/images/news_685e6898c86d33.08760966.png', '[[v4green]]RaiseMTA', 'admin');
